INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('4d446438-7613-43d2-b95e-c6f1acf9109d'::uuid, 'card_description', 'Big-game hunting gives way to herding in the figures of this rock art. Along a river valley, the figures, over 10,000 of them, go on to show nomads who depended on horses.', '~10,000 figures carved across 15 sq km in the Tsagaan Salaa valley of Altai Tavan Bogd. A UNESCO site spanning Neolithic to Bronze Age - one of Central Asia''s largest petroglyph archives.', 'teaser-card-s042-rollback:4d446438-7613-43d2-b95e-c6f1acf9109d:card_description', 'rollback of teaser-card-s042: card_description "~10,000 figures carved across 15 sq km in the Tsagaan Salaa valley of Altai Tavan Bogd. A UNESCO site spanning Neolithic to Bronze Age - one of Central Asia''s largest petroglyph archives." restored on Tsagaan Salaa Rock Paintings', '3d26481654308afe90ff4da7f13a781affe835d8fa555cac81f20efd43d2bdb1|94ab6d8c8b9e4effca03fe0022b9d799a90264b7e936756973df715653539d24|94ab6d8c8b9e4effca03fe0022b9d799a90264b7e936756973df715653539d24', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Big-game hunting gives way to herding in the figures of this rock art. Along a river valley, the figures, over 10,000 of them, go on to show nomads who depended on horses."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "it is rock art [S1]; the figures show the shift from big-game hunting to herding [S3]; the site runs along a river valley [S2]; there are over 10,000 figures [S2]; the figures show horse-dependent nomadism [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "This is a rock art site: its figures are carved on rocks [SUPPORTED: https://insightmongolia.com/destinations/bayan-ulgii/rock-petroglyphs-of-tsagaan-salaa,-baga-oigor]; The earlier figures show big-game hunting [SUPPORTED: https://en.wikipedia.org/wiki/List_of_World_Heritage_Sites_in_Mongolia]; In the figures, hunting gives way to herding [SUPPORTED: https://en.wikipedia.org/wiki/List_of_World_Heritage_Sites_in_Mongolia]; The rock art lies along a river valley [SUPPORTED: https://www.mongolia-trips.com/guide-mongolie/attraction/the-rock-paintings-of-tsagaan-salaa]; There are over 10,000 figures [SUPPORTED: https://www.mongolian.travel/tsagaan-salaa-paintings/]; The figures go on to show nomads who depended on horses [SUPPORTED: https://en.wikipedia.org/wiki/List_of_World_Heritage_Sites_in_Mongolia]"}]'::jsonb),
    ('4f32070e-25b0-4f96-a895-37499099f745'::uuid, 'card_description', 'Nothing of this Neolithic site shows at ground level. Birmingham Archaeology probed the site from 2002 to 2004, and from the air the features appear as cropmarks.', 'Near the River Trent, the Catholme Ceremonial Complex is a Neolithic site that Birmingham Archaeology investigated from 2002 to 2004 with a geophysical survey, Lidar and excavation.', 'teaser-card-s042-rollback:4f32070e-25b0-4f96-a895-37499099f745:card_description', 'rollback of teaser-card-s042: card_description ''Near the River Trent, the Catholme Ceremonial Complex is a Neolithic site that Birmingham Archaeology investigated from 2002 to 2004 with a geophysical survey, Lidar and excavation.'' restored on Catholme Ceremonial Complex', 'b22e061ec8c8e7f0180b49f46eb34f78eefcf6471a6e5af2f7344bd2ac3a5942|844e1f2c1b664e8ef170417618f5133b5a6062cc82717618066b58025398d399|844e1f2c1b664e8ef170417618f5133b5a6062cc82717618066b58025398d399', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Nothing of this Neolithic site shows at ground level. Birmingham Archaeology probed the site from 2002 to 2004, and from the air the features appear as cropmarks."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is Neolithic [S1]; its features are not visible at ground level [S3]; Birmingham Archaeology investigated the site [S4]; the investigation ran from 2002 to 2004 [S4]; the features are visible from the air as cropmarks [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "This is a Neolithic (ceremonial) site [SUPPORTED: https://www.cambridge.org/core/journals/proceedings-of-the-prehistoric-society/article/abs/catholme-ceremonial-complex-staffordshire-uk/3745F76CCD6BA119043EC1E2B9E610BE]; Nothing of the site shows at ground level [SUPPORTED: https://www.thetrentvalley.org.uk/projects/tttv-heritage/birthplace-of-a-goddess/]; Birmingham Archaeology probed the site [SUPPORTED: https://www.digitaldigging.net/catholme-neolithic-complex-timber-circles/]; The investigation ran from 2002 to 2004 [SUPPORTED: https://www.digitaldigging.net/catholme-neolithic-complex-timber-circles/]; From the air, the features appear as cropmarks [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=14862]"}]'::jsonb),
    ('521ade1a-0eaf-442b-973d-ccae9e9fbb35'::uuid, 'card_description', 'Found in two pieces, this granite stone was rejoined in the 1990s. The giant is believed to be the largest standing stone of the Iberian Peninsula carved entirely by humans.', 'Found in two pieces in 1965 and rejoined in the 1990s, the Menhir of Meada measures about 7.5 metres, weighs around 18 tons and is believed to have been raised around 5000 BCE.', 'teaser-card-s042-rollback:521ade1a-0eaf-442b-973d-ccae9e9fbb35:card_description', 'rollback of teaser-card-s042: card_description ''Found in two pieces in 1965 and rejoined in the 1990s, the Menhir of Meada measures about 7.5 metres, weighs around 18 tons and is believed to have been raised around 5000 BCE.'' restored on Menhir of Meada', 'ec7fa3995baa1adf20df526f22928a719f3e221e3d1245b5113f5a6e389585e2|e6fba3ceb99bf35a66ebd49bcc1402529ea1709b39c8ca66a389e1b28b5ca7dc|e6fba3ceb99bf35a66ebd49bcc1402529ea1709b39c8ca66a389e1b28b5ca7dc', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Found in two pieces, this granite stone was rejoined in the 1990s. The giant is believed to be the largest standing stone of the Iberian Peninsula carved entirely by humans."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the stone was found in two pieces [S4]; the stone is granite [S3]; it was rejoined in the 1990s [S4]; it is a giant stone [S1, S5, S6]; it is believed to be the largest standing stone of the Iberian Peninsula carved entirely by humans [S1]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Found in two pieces, this granite stone was rejoined in the 1990s. [SUPPORTED: https://web.archive.org/web/2025/https://imovel.patrimoniocultural.gov.pt/detalhes.php?code=70245]; The stone was found in two pieces. [SUPPORTED: https://web.archive.org/web/2025/https://imovel.patrimoniocultural.gov.pt/detalhes.php?code=70245]; The stone is granite. [SUPPORTED: https://web.archive.org/web/2025/https://imovel.patrimoniocultural.gov.pt/detalhes.php?code=70245]; The two pieces were rejoined in the 1990s. [SUPPORTED: https://web.archive.org/web/2025/https://www.nationalgeographic.pt/historia/menir-da-meada-o-mais-antigo_2725]; The stone is a giant. [SUPPORTED: https://web.archive.org/web/2025/https://www.nationalgeographic.pt/historia/menir-da-meada-o-mais-antigo_2725]; It is a standing stone. [SUPPORTED: https://web.archive.org/web/2025/https://www.nationalgeographic.pt/historia/menir-da-meada-o-mais-antigo_2725]; It is believed to be the largest standing stone of the Iberian Peninsula carved entirely by humans. [SUPPORTED: https://web.archive.org/web/2025/https://imovel.patrimoniocultural.gov.pt/detalhes.php?code=70245]"}]'::jsonb),
    ('539b56ad-5705-40c1-848b-767710247e7c'::uuid, 'card_description', 'Diggers found the remains of some 15 to 30 people in this low stone chamber. Its roof is one very large slab, resting on only three of the uprights, and half of their height lies buried.', 'Under a roof slab estimated at 25 tonnes, the uprights of Lligwy Burial Chamber on Anglesey hide half their height underground. In 1909 excavators found the remains of some 15 to 30 people.', 'teaser-card-s042-rollback:539b56ad-5705-40c1-848b-767710247e7c:card_description', 'rollback of teaser-card-s042: card_description ''Under a roof slab estimated at 25 tonnes, the uprights of Lligwy Burial Chamber on Anglesey hide half their height underground. In 1909 excavators found the remains of some 15 to 30 people.'' restored on Lligwy Burial Chamber', 'e9641cbcc6df0c9c6bbefc297b8e25a1a5e91e280e3e7dfdab37ab345f1890d2|237e5a950ee7e144205d7c160317986122f6f515b062be5d7f72aec32cd429f5|237e5a950ee7e144205d7c160317986122f6f515b062be5d7f72aec32cd429f5', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Diggers found the remains of some 15 to 30 people in this low stone chamber. Its roof is one very large slab, resting on only three of the uprights, and half of their height lies buried."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "excavators found remains of some 15 to 30 people [S3]; it is a low stone chamber [S2]; its roof is one very large slab [S2]; the roof slab rests on only three of the uprights [S6]; half of the uprights'' height is buried [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Diggers found the remains of some 15 to 30 people in this chamber. [SUPPORTED: https://www.anglesey-history.co.uk/places/lligwy/]; It is a low stone chamber. [SUPPORTED: http://www.stone-circles.org.uk/stone/lligwy.htm]; Its roof is one very large slab. [SUPPORTED: https://cadw.gov.wales/visit/places-to-visit/lligwy-burial-chamber]; The roof slab rests on only three of the uprights. [SUPPORTED: http://www.stone-circles.org.uk/stone/lligwy.htm]; Half of the uprights'' height lies buried. [SUPPORTED: http://www.stone-circles.org.uk/stone/lligwy.htm]"}]'::jsonb),
    ('561ba9a0-09a5-4954-b137-f5c7dbdb0349'::uuid, 'card_description', 'An emperor born in the city raised this beacon tower over its harbour. Septimius Severus also expanded that harbour, and his tower of many stories reached about 35 metres in height.', '6th-century BC Phoenician lighthouse at Leptis Magna Harbour, a port that passed from Phoenician to Carthaginian to Roman rule. The ancient tower that guided ships is now slowly eroded by the sea.', 'teaser-card-s042-rollback:561ba9a0-09a5-4954-b137-f5c7dbdb0349:card_description', 'rollback of teaser-card-s042: card_description ''6th-century BC Phoenician lighthouse at Leptis Magna Harbour, a port that passed from Phoenician to Carthaginian to Roman rule. The ancient tower that guided ships is now slowly eroded by the sea.'' restored on Lighthouse of Leptis Magna', 'beaa6a0fcc6ec4a47abd1c3616b46444cc37842e2e983508a1fd765f4d48acb6|927c6eb383f19d114f14266ccf5761ae856df842fa16a2224df6511ee1d177ad|927c6eb383f19d114f14266ccf5761ae856df842fa16a2224df6511ee1d177ad', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An emperor born in the city raised this beacon tower over its harbour. Septimius Severus also expanded that harbour, and his tower of many stories reached about 35 metres in height."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "an emperor was born in the city [S2]; that emperor built this lighthouse tower [S2]; the tower stood at the city''s harbour [S1]; the emperor was Septimius Severus [S2]; Septimius Severus expanded the harbour [S2]; the tower had several stories [S2]; the tower reached about 35 metres in height [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An emperor born in the city raised this beacon tower over its harbour. [SUPPORTED: https://pharos.cealex.org/ancient-lighthouses/]; The emperor who raised the tower was Septimius Severus. [SUPPORTED: https://pharos.cealex.org/ancient-lighthouses/]; The structure is a beacon tower (lighthouse). [SUPPORTED: https://pharos.cealex.org/ancient-lighthouses/]; The emperor, Septimius Severus, was born in the city. [SUPPORTED: https://www.ancientportsantiques.com/a-few-ports/leptis-magna/]; The tower was raised over the city''s harbour. [SUPPORTED: https://www.livius.org/articles/place/lepcis-magna/photos/lepcis-magna-port/]; Septimius Severus also expanded that harbour. [SUPPORTED: https://www.livius.org/articles/place/lepcis-magna/photos/lepcis-magna-port/]; His tower had many stories. [SUPPORTED: https://www.livius.org/articles/place/lepcis-magna/photos/lepcis-magna-port/]; The tower reached about 35 metres in height. [SUPPORTED: https://pharos.cealex.org/ancient-lighthouses/]"}]'::jsonb),
    ('56876b69-7222-4afd-8204-5f1f00bd0725'::uuid, 'card_description', 'A bronze sword and a gilt belt hook lay in a Bronze Age grave here. They bore the same motif as two engraved granite stones at the site, proof that the mound and the stones are of one date.', 'In Øster Velling Skov forest, two granite boulders at Mandbjerghøj bear Bronze Age concentric rings and ovals, the same motif found on a gilt belt-hook in the grave of the nearby tumulus.', 'teaser-card-s042-rollback:56876b69-7222-4afd-8204-5f1f00bd0725:card_description', 'rollback of teaser-card-s042: card_description ''In Øster Velling Skov forest, two granite boulders at Mandbjerghøj bear Bronze Age concentric rings and ovals, the same motif found on a gilt belt-hook in the grave of the nearby tumulus.'' restored on Mandbjerghøj', '386408d8d062867c8b5c7b6aac213e057eb2d336ac1c0b3dcc6e36b6a2e815f4|19ed099530f686e703a60c23796db1f9713a06c7376197fce1b156f355d1d449|19ed099530f686e703a60c23796db1f9713a06c7376197fce1b156f355d1d449', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A bronze sword and a gilt belt hook lay in a Bronze Age grave here. They bore the same motif as two engraved granite stones at the site, proof that the mound and the stones are of one date."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a bronze sword was found in a grave here [S6, S7]; a gilt belt hook was found in the same grave [S7]; the grave is of the Bronze Age [S6]; the sword and belt hook bore the same motif as the engraved stones [S7]; there are two engraved granite stones at the site [S2]; this proves the mound and the engraved stones date from the same time [S7]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A bronze sword and a gilt belt hook lay in a Bronze Age grave here. [SUPPORTED: https://fortidsmindeguide.dk/tidsalder/bronzealder/mandbjerghoj-gravhoj]; The grave held a bronze sword. [SUPPORTED: https://trap.lex.dk/Mandbjerg/Mandbjergh%C3%B8j]; The grave held a gilt belt hook. [SUPPORTED: https://trap.lex.dk/Mandbjerg/Mandbjergh%C3%B8j]; The grave dates to the Bronze Age. [SUPPORTED: https://fortidsmindeguide.dk/tidsalder/bronzealder/mandbjerghoj-gravhoj]; There are two engraved granite stones at the site. [SUPPORTED: https://fortidsmindeguide.dk/tidsalder/bronzealder/mandbjerghoj-gravhoj]; The sword and belt hook bore the same motif as the engraved stones. [SUPPORTED: https://fortidsmindeguide.dk/tidsalder/bronzealder/mandbjerghoj-gravhoj]; The shared motif is proof that the mound and the stones are of one date. [SUPPORTED: https://fortidsmindeguide.dk/tidsalder/bronzealder/mandbjerghoj-gravhoj]; The grave lay in a mound at the site. [SUPPORTED: https://www.randers.dk/oplev/besoeg-naturen/naturture/helleristningsstenene-og-oester-velling-skov/]"}]'::jsonb),
    ('56f3ec0c-0610-4701-8a4e-727b7d3a2512'::uuid, 'card_description', 'Foundations of 160 round stone structures sit on this butte. Over 460 rock carvings and a prehistoric garden beside the hill show how much it mattered to the ancient Hohokam.', 'West of downtown Tucson rises Tumamoc Hill, once home to the ancient Hohokam: 160 round stone foundations of the earliest known trincheras village, walls of stone and over 460 petroglyphs.', 'teaser-card-s042-rollback:56f3ec0c-0610-4701-8a4e-727b7d3a2512:card_description', 'rollback of teaser-card-s042: card_description ''West of downtown Tucson rises Tumamoc Hill, once home to the ancient Hohokam: 160 round stone foundations of the earliest known trincheras village, walls of stone and over 460 petroglyphs.'' restored on Tumamoc Hill', '74d32cf4ef26d2512536de023f0a754964c40e984984720b8d5775bf3ecea977|847367a98364369a38094a25439478012fdbae12ee7304b054ae9611fa2ed064|847367a98364369a38094a25439478012fdbae12ee7304b054ae9611fa2ed064', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Foundations of 160 round stone structures sit on this butte. Over 460 rock carvings and a prehistoric garden beside the hill show how much it mattered to the ancient Hohokam."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "there are foundations of 160 round stone structures [S3]; the site is a butte [S1]; there are over 460 rock carvings (petroglyphs) [S4]; there is a prehistoric garden beside the hill [S4]; these show the hill''s importance to its people [S4]; those people were the ancient Hohokam [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Foundations of 160 stone structures sit on this hill (Tumamoc Hill) [SUPPORTED: https://npshistory.com/publications/nr-forms/az/tumamoc-hill-archaeological-site.pdf]; The 160 stone structures are round [SUPPORTED: https://npshistory.com/publications/nr-forms/az/tumamoc-hill-archaeological-site.pdf]; The site is a butte [SUPPORTED: https://npshistory.com/publications/nr-forms/az/tumamoc-hill-archaeological-site.pdf]; There are over 460 rock carvings [SUPPORTED: https://npshistory.com/publications/nr-forms/az/tumamoc-hill-archaeological-site.pdf]; There is a prehistoric garden beside the hill [SUPPORTED: https://tumamoc.org/timeline.html]; The rock carvings and the garden show how much the hill mattered to the ancient Hohokam [SUPPORTED: https://tumamoc.org/timeline.html]"}]'::jsonb),
    ('577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1'::uuid, 'card_description', 'Of three hill forts on this hill, quarrying has largely taken two. The last ''intact'' survivor sits on a sloping ridge top, with ramparts up to three metres high and a commanding view.', 'On Brown Clee Hill, the highest hill in Shropshire, Nordy Bank''s ramparts still rise up to three metres, the last survivor of three Iron Age hill forts; two were largely lost to quarrying.', 'teaser-card-s042-rollback:577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1:card_description', 'rollback of teaser-card-s042: card_description "On Brown Clee Hill, the highest hill in Shropshire, Nordy Bank''s ramparts still rise up to three metres, the last survivor of three Iron Age hill forts; two were largely lost to quarrying." restored on Brown Clee Hill', '0e4aa899b754289d0fe9e65380602d5298568ea3925b3f468e3e6475b9a450b7|c8a5972d52a530e7164770359414162d8eea0f95a7590b1265708b5a047084db|c8a5972d52a530e7164770359414162d8eea0f95a7590b1265708b5a047084db', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Of three hill forts on this hill, quarrying has largely taken two. The last ''intact'' survivor sits on a sloping ridge top, with ramparts up to three metres high and a commanding view."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "there were three hill forts on this hill [S3]; two of them have been largely lost to quarrying [S4]; one is the last ''intact'' survivor [S3]; the survivor sits on a sloping ridge top [S5]; its ramparts are up to three metres high [S5]; it has a commanding view [S6]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "The last ''intact'' survivor of the hill forts on this hill (Nordy Bank on Brown Clee Hill) [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN0073.html]; There are three hill forts on this hill [SUPPORTED: http://www.walkingenglishman.com/outandabout/centralengland/35cockshutford.html]; Quarrying has largely taken two of the three hill forts [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=4934]; The survivor sits on a ridge top [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN0073.html]; The ridge top is sloping [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN0073.html]; Its ramparts are up to three metres high [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN0073.html]; It has a commanding view [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN0073.html]"}]'::jsonb),
    ('585ae9f5-c9ef-4446-84e9-a2c5825f5eda'::uuid, 'card_description', 'Japanese found this two-room tomb during their occupation of the peninsula. Its back room holds a painting on the north wall, and the Koguryo tomb is now listed as a National Treasure.', 'A two-chambered Goguryeo tomb (37 BC-668 AD) with plaster walls once decorated with chariots, musicians, and horsemen. Nearly all the paintings have now vanished.', 'teaser-card-s042-rollback:585ae9f5-c9ef-4446-84e9-a2c5825f5eda:card_description', 'rollback of teaser-card-s042: card_description ''A two-chambered Goguryeo tomb (37 BC-668 AD) with plaster walls once decorated with chariots, musicians, and horsemen. Nearly all the paintings have now vanished.'' restored on Twin Column Tomb', '1dc794cef5f6e88c22e390062150490effa8d5d288f863020cc82ea238bb8770|d0719bd1bc42223a5064a301334f627444209f6fc08a27f9c8a15b7d47e5e97a|d0719bd1bc42223a5064a301334f627444209f6fc08a27f9c8a15b7d47e5e97a', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Japanese found this two-room tomb during their occupation of the peninsula. Its back room holds a painting on the north wall, and the Koguryo tomb is now listed as a National Treasure."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the tomb was discovered by Japanese [S3]; it was discovered during Japan''s occupation of the peninsula [S3]; the tomb has two chambers [S1]; the back chamber has a painting on its north wall [S2]; the tomb dates from the Koguryo period [S1]; the tomb is listed as a National Treasure [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Japanese found this tomb (the Twin Column Tomb) [SUPPORTED: http://dh.aks.ac.kr/Encyves/wiki/index.php/%EC%8C%8D%EC%98%81%EC%B4%9D]; The Japanese found it during their occupation of the peninsula [SUPPORTED: http://dh.aks.ac.kr/Encyves/wiki/index.php/%EC%8C%8D%EC%98%81%EC%B4%9D]; It is a two-room tomb [SUPPORTED: https://encykorea.aks.ac.kr/Article/E0034153]; Its back room holds a painting on the north wall [SUPPORTED: https://encykorea.aks.ac.kr/Article/E0034153]; It is a Koguryo tomb [SUPPORTED: https://encykorea.aks.ac.kr/Article/E0034153]; The tomb is now listed as a National Treasure [SUPPORTED: https://en.wikipedia.org/wiki/National_Treasure_(North_Korea)]"}]'::jsonb),
    ('59a722b9-4281-4426-8144-284e509f2061'::uuid, 'card_description', 'Dynamite brought down the clock tower that once stood on this Roman bastion. Emperor Hadrian''s fortress of the 2nd century AD had four corner towers, and the bastion is the sole survivor.', '2nd century AD. Part of Rome''s city fortifications, this 48 m octagonal tower was rebuilt after fire in 1894 and damaged by earthquake in 1953 — yet it still carries a working clock.', 'teaser-card-s042-rollback:59a722b9-4281-4426-8144-284e509f2061:card_description', 'rollback of teaser-card-s042: card_description "2nd century AD. Part of Rome''s city fortifications, this 48 m octagonal tower was rebuilt after fire in 1894 and damaged by earthquake in 1953 — yet it still carries a working clock." restored on Macedonian Tower', '4d0aae3dbc47a0b5b17719fd6f657a8c388f59f9a7009b957b131aa534e8ace6|c4785df55db1a724dcc96831a327e3815d9c894021ee9aeb467b03501a7cd1bd|c4785df55db1a724dcc96831a327e3815d9c894021ee9aeb467b03501a7cd1bd', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Dynamite brought down the clock tower that once stood on this Roman bastion. Emperor Hadrian''s fortress of the 2nd century AD had four corner towers, and the bastion is the sole survivor."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a clock tower once stood on this bastion [S3]; dynamite brought the clock tower down [S3]; the bastion is Roman [S1]; the fortress was Emperor Hadrian''s [S1]; the fortress dates from the 2nd century AD [S1]; the fortress had four corner towers [S2]; this bastion is the sole surviving one [S1]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Dynamite brought down the clock tower that once stood on this bastion (the Macedonian Tower in Edirne) [SUPPORTED: https://www.hurriyetdailynews.com/edirne-revives-ancient-tower-with-galata-inspired-concept-213176]; A clock tower once stood on this bastion [SUPPORTED: https://turkisharchaeonews.net/object/fortifications-and-macedonian-tower-edirne]; The bastion is Roman [SUPPORTED: https://www.hurriyetdailynews.com/edirne-revives-ancient-tower-with-galata-inspired-concept-213176]; The fortress was Emperor Hadrian''s [SUPPORTED: https://turkisharchaeonews.net/object/fortifications-and-macedonian-tower-edirne]; The fortress dates to the 2nd century AD [SUPPORTED: https://www.hurriyetdailynews.com/edirne-revives-ancient-tower-with-galata-inspired-concept-213176]; The fortress had four corner towers [SUPPORTED: https://turkisharchaeonews.net/object/fortifications-and-macedonian-tower-edirne]; The bastion is the sole survivor of the four corner towers [SUPPORTED: https://turkisharchaeonews.net/object/fortifications-and-macedonian-tower-edirne]"}]'::jsonb),
    ('5df03f8d-0b22-4188-b7ae-ccd2b00d8f47'::uuid, 'card_description', 'Stone monuments at two Maya cities record king Ch''iyel''s visit to Ixkun. His city sat on a key trade route through the Maya Mountains, and the two appear to have formed a military alliance.', 'Sacul, a Maya city on a trade route through the Maya Mountains, lost a war to Ixkun in AD 779. Just 11 years later its king Ch''iyel visited Ixkun, and the two appear to have become allies.', 'teaser-card-s042-rollback:5df03f8d-0b22-4188-b7ae-ccd2b00d8f47:card_description', 'rollback of teaser-card-s042: card_description "Sacul, a Maya city on a trade route through the Maya Mountains, lost a war to Ixkun in AD 779. Just 11 years later its king Ch''iyel visited Ixkun, and the two appear to have become allies." restored on Sacul', 'a3b4ac74c7c210affa98cb5383335eb8efd94033f494aadfd64a973eba7bfcdf|b7372866d6605dc8d0b1641fe71b767087de7823518f61fa4e978d2fa7bf115c|b7372866d6605dc8d0b1641fe71b767087de7823518f61fa4e978d2fa7bf115c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Stone monuments at two Maya cities record king Ch''iyel''s visit to Ixkun. His city sat on a key trade route through the Maya Mountains, and the two appear to have formed a military alliance."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "stone monuments (stelae) at two Maya cities record a visit [S5]; the visit was king Ch''iyel''s visit to Ixkun [S5]; Ch''iyel''s city sat on a key trade route [S2, S5]; the trade route ran through the Maya Mountains [S2]; the two cities appear to have formed a military alliance [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Stone monuments at two Maya cities record king Ch''iyel''s visit to Ixkun. [SUPPORTED: https://dialnet.unirioja.es/descarga/articulo/2774793.pdf]; Ch''iyel was the king of this city. [SUPPORTED: https://www.mesoweb.com/pari/publications/journal/1904/YellowTree.pdf]; His city sat on a trade route through the Maya Mountains. [SUPPORTED: http://www.asociaciontikal.com/simposio-04-ano-1990/10-el-valle-de-sacul-en-las-montanas-mayas-de-guatemala-juan-pedro-laporte-rolando-torres-hector-escobedo-y-paulino-morales-simposio-04-ano-1990/]; The trade route was a key one. [SUPPORTED: http://www.asociaciontikal.com/simposio-04-ano-1990/10-el-valle-de-sacul-en-las-montanas-mayas-de-guatemala-juan-pedro-laporte-rolando-torres-hector-escobedo-y-paulino-morales-simposio-04-ano-1990/]; The two appear to have formed a military alliance. [SUPPORTED: https://www.cambridge.org/core/services/aop-cambridge-core/content/view/F43EC3F70B5295D42D2FBDBCE7D167B6/S095653612510076Xa.pdf/the-enemy-of-my-enemy-ixkun-stela-4-and-classic-maya-international-politics-on-the-eve-of-war.pdf]"}]'::jsonb),
    ('5e13b5f1-b63f-49fa-96e9-7adad6c1d136'::uuid, 'card_description', 'Probably built in the Punic Wars, this round tower fell in the 3rd century AD. About seven wall courses high, the tower is the best preserved of the country''s Punic-Roman towers.', 'The best-preserved of six Punic-Roman towers, standing seven courses high with 3 m thick walls at the base. It served from the Punic Wars into Roman times.', 'teaser-card-s042-rollback:5e13b5f1-b63f-49fa-96e9-7adad6c1d136:card_description', 'rollback of teaser-card-s042: card_description ''The best-preserved of six Punic-Roman towers, standing seven courses high with 3 m thick walls at the base. It served from the Punic Wars into Roman times.'' restored on Ta'' Ġawhar Tower', '34356a5a7f7964e9d65d89900e3941bbfd76a63ad9f06884bee9a184e15c77aa|ad8d1986856536ce8a6fb40e3178b7b525210a08b69edfff82eedfd2b5c3909e|ad8d1986856536ce8a6fb40e3178b7b525210a08b69edfff82eedfd2b5c3909e', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Probably built in the Punic Wars, this round tower fell in the 3rd century AD. About seven wall courses high, the tower is the best preserved of the country''s Punic-Roman towers."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the tower was probably built in the Punic Wars [S3]; it is a round tower [S1]; it was destroyed (fell) in the 3rd century AD [S3]; it stands about seven wall courses high [S2]; it is the best preserved of the country''s Punic-Roman towers [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "The tower is the best preserved of the country''s Punic-Roman towers. [SUPPORTED: https://en.wikipedia.org/wiki/Punic-Roman_towers_in_Malta]; It is a round tower. [SUPPORTED: https://web.archive.org/web/20150528140134/http://www.culturalheritage.gov.mt/filebank/inventory/00021.pdf]; It was probably built in the Punic Wars. [SUPPORTED: https://en.wikipedia.org/wiki/Punic-Roman_towers_in_Malta]; The tower fell in the 3rd century AD. [SUPPORTED: https://web.archive.org/web/20150528140134/http://www.culturalheritage.gov.mt/filebank/inventory/00021.pdf]; The tower is about seven wall courses high. [SUPPORTED: https://web.archive.org/web/20150528140134/http://www.culturalheritage.gov.mt/filebank/inventory/00021.pdf]; It is one of the country''s Punic-Roman towers. [SUPPORTED: https://en.wikipedia.org/wiki/Punic-Roman_towers_in_Malta]"}]'::jsonb),
    ('5f22c11c-22a4-4776-9120-75b3b9e33687'::uuid, 'card_description', 'Each winter, this floor is covered for protection, then reopened in spring. Colorful marble pieces show a figure from myth in a rare technique, one of the few surviving examples worldwide.', '1st century AD. A Medusa floor mosaic in the ancient city of Kibyra, 95% intact. Made by Opus Sectile — red, green, and white marble forming a gorgon''s face with serpent hair and petrifying eyes.', 'teaser-card-s042-rollback:5f22c11c-22a4-4776-9120-75b3b9e33687:card_description', 'rollback of teaser-card-s042: card_description "1st century AD. A Medusa floor mosaic in the ancient city of Kibyra, 95% intact. Made by Opus Sectile — red, green, and white marble forming a gorgon''s face with serpent hair and petrifying eyes." restored on Medusa Mozaiği', '5b4104b2b47767e2c6acd56bbc4a2e592a6f823f73f31f16f528eb108778b45f|b85e24939f96a9c80dff6e29b23e9f5f19596ce15f066f678fdbc8f816881fd6|b85e24939f96a9c80dff6e29b23e9f5f19596ce15f066f678fdbc8f816881fd6', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Each winter, this floor is covered for protection, then reopened in spring. Colorful marble pieces show a figure from myth in a rare technique, one of the few surviving examples worldwide."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "it is a floor [S1]; it is covered each winter for protection [S4]; it is reopened each spring [S4]; it is made of colorful marble pieces [S2]; it shows a mythological figure [S2]; it uses a rare technique [S2]; it is one of the few surviving examples of that technique worldwide [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Each winter, this floor is covered for protection [SUPPORTED: https://www.iletisim.gov.tr/turkce/yerel_basin/detay/medusa-mozaigi-ziyarete-acildi]; It is reopened in spring [SUPPORTED: https://www.anatolianarchaeology.net/a-nearly-intact-medusa-mosaic-at-ancient-kibyra-is-temporarily-closed-to-protect-it-from-winter-damage/]; It is a floor [SUPPORTED: https://www.iletisim.gov.tr/turkce/yerel_basin/detay/medusa-mozaigi-ziyarete-acildi]; It is made of colorful marble pieces [SUPPORTED: https://www.iletisim.gov.tr/turkce/yerel_basin/detay/medusa-mozaigi-ziyarete-acildi]; It shows a figure from myth [SUPPORTED: https://www.iletisim.gov.tr/turkce/yerel_basin/detay/medusa-mozaigi-ziyarete-acildi]; It is made in a rare technique [SUPPORTED: https://www.dailysabah.com/arts/medusa-mosaic-closed-9-months-a-year-accepts-visitors-through-september/news]; It is one of the few surviving examples worldwide [SUPPORTED: https://haberton.com/kisin-uzeri-kapatilan-medusa-mozaigi-ziyarete-acildi/]"}]'::jsonb),
    ('655898a6-3d5c-40f3-8411-e6b3b185f11f'::uuid, 'card_description', 'Thousands of terracotta roof pieces lay in the debris of this building. The Early Bronze Age house had two stories, a stairway and storage areas, until fire finally destroyed the house.', 'At Lerna, the House of the Tiles rose two stories under a roof of baked tiles; thousands of its terracotta tiles lay fallen in the debris. Fire finally destroyed it in the 22nd century BC.', 'teaser-card-s042-rollback:655898a6-3d5c-40f3-8411-e6b3b185f11f:card_description', 'rollback of teaser-card-s042: card_description ''At Lerna, the House of the Tiles rose two stories under a roof of baked tiles; thousands of its terracotta tiles lay fallen in the debris. Fire finally destroyed it in the 22nd century BC.'' restored on House of the Tiles', '62e2706659dafd0418ae633e29fe9f4b5dc4ff2ea39067e0dcea3d0ba0fa41ca|a7ded7ff33d76235ba3fc601b42baa1dc67c7966bbd2e0f1adc680e4a414db1a|a7ded7ff33d76235ba3fc601b42baa1dc67c7966bbd2e0f1adc680e4a414db1a', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Thousands of terracotta roof pieces lay in the debris of this building. The Early Bronze Age house had two stories, a stairway and storage areas, until fire finally destroyed the house."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-005 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "thousands of terracotta roof tiles lay in the debris [S6]; the tiles had fallen from this building''s roof [S6]; it is an Early Bronze Age house [S1, S5]; it had two stories [S1]; it had a stairway [S5]; it had storage areas [S5]; fire finally destroyed the house [S8]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Thousands of terracotta roof pieces belonged to this building. [SUPPORTED: https://www.ime.gr/chronos//02/mainland/en/eh/habitation/architecture/corridor.html]; The roof pieces lay in the debris of the building. [SUPPORTED: https://www.greeknewsagenda.gr/lerna-a-gateway-to-prehistoric-greece-and-mythology/]; The roof pieces were of terracotta. [SUPPORTED: https://sites.dartmouth.edu/aegean-prehistory/lessons/lesson-3-narrative/]; It is an Early Bronze Age house. [SUPPORTED: https://www.ascsa.edu.gr/publications/book/?i=9780876619223]; The house had two stories. [SUPPORTED: https://sites.dartmouth.edu/aegean-prehistory/lessons/lesson-3-narrative/]; The house had a stairway. [SUPPORTED: https://sites.dartmouth.edu/aegean-prehistory/lessons/lesson-3-narrative/]; The house had storage areas. [SUPPORTED: https://www.ime.gr/chronos//02/mainland/en/eh/habitation/architecture/corridor.html]; Fire finally destroyed the house. [SUPPORTED: https://sites.dartmouth.edu/aegean-prehistory/lessons/lesson-3-narrative/]"}]'::jsonb),
    ('657dbfe1-7b3f-4548-93c6-99be8674a6ff'::uuid, 'card_description', 'James Farrer and George Petrie dug into this Neolithic tomb in 1867. They uncovered the bones of several people in a tomb similar in design to Maeshowe, later partly restored.', 'On the Elsness peninsula of Sanday, Orkney, the Quoyness Chambered Cairn rests on an oval stone platform. Probably built around 3000 BC, it gave up the bones of several people in 1867.', 'teaser-card-s042-rollback:657dbfe1-7b3f-4548-93c6-99be8674a6ff:card_description', 'rollback of teaser-card-s042: card_description ''On the Elsness peninsula of Sanday, Orkney, the Quoyness Chambered Cairn rests on an oval stone platform. Probably built around 3000 BC, it gave up the bones of several people in 1867.'' restored on Quoyness Chambered Cairn', 'c835224d9363c297ef2848496e5ff94198bf1dbaf7c29a702843d6135ee70e44|0bc31fbb8dade0d8224c3d3312f7c9fb6048df517dc722efea2ac4eb7bedb527|0bc31fbb8dade0d8224c3d3312f7c9fb6048df517dc722efea2ac4eb7bedb527', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "James Farrer and George Petrie dug into this Neolithic tomb in 1867. They uncovered the bones of several people in a tomb similar in design to Maeshowe, later partly restored."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "James Farrer and George Petrie excavated the tomb [S8]; they excavated it in 1867 [S8]; it is a Neolithic tomb [S1]; the remains of several people were uncovered in that excavation [S3, S8]; the tomb is similar in design to Maeshowe [S2]; the tomb was later partially restored [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "James Farrer and George Petrie dug into this tomb [SUPPORTED: https://www.orkneystonetools.org.uk/themes/sites/funerary/quoyness]; They dug into it in 1867 [SUPPORTED: https://www.orkneystonetools.org.uk/themes/sites/funerary/quoyness]; It is a Neolithic tomb [SUPPORTED: https://www.historicenvironment.scot/visit-a-place/places/quoyness-chambered-cairn/history/]; They uncovered the bones of several people [SUPPORTED: https://www.orkneystonetools.org.uk/themes/sites/funerary/quoyness]; The tomb is similar in design to Maeshowe [SUPPORTED: https://www.orkneystonetools.org.uk/themes/sites/funerary/quoyness]; The tomb was later partly restored [SUPPORTED: https://www.orkneystonetools.org.uk/themes/sites/funerary/quoyness]"}]'::jsonb),
    ('6814a205-8ebc-46b8-8581-94c1cbb06745'::uuid, 'card_description', 'Miners here broke the rock with fire-setting and thermal shock. Shafts follow veins of copper ore, some 15-20 metres into the hillside, in one of the earliest copper mines in Europe.', '5th-millennium BC copper mine with shafts cut into the hillside and scaffolding for ore access — among the earliest evidence of European copper mining. Pottery links it firmly to the Vinča culture.', 'teaser-card-s042-rollback:6814a205-8ebc-46b8-8581-94c1cbb06745:card_description', 'rollback of teaser-card-s042: card_description ''5th-millennium BC copper mine with shafts cut into the hillside and scaffolding for ore access — among the earliest evidence of European copper mining. Pottery links it firmly to the Vinča culture.'' restored on Rudna Glava', 'df99d850b4167af0cc3375c3929fe4e8a352da2caad848238074da5a9a0b025f|4cdd3fcf07c0fadf32055479b29cb89ed98c13ffd35823fa1e4714db3af1ab86|4cdd3fcf07c0fadf32055479b29cb89ed98c13ffd35823fa1e4714db3af1ab86', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Miners here broke the rock with fire-setting and thermal shock. Shafts follow veins of copper ore, some 15-20 metres into the hillside, in one of the earliest copper mines in Europe."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "miners broke rock with fire-setting [S3]; miners used thermal shock [S3]; mine shafts follow veins of copper ore [S2]; some shafts extend 15-20 metres into the hillside [S2]; it is one of the earliest copper mines in Europe [S1]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "This is one of the earliest copper mines in Europe [SUPPORTED: https://www.penn.museum/sites/expedition/the-oldest-copper-metallurgy-in-the-balkans/]; Copper ore was mined here [SUPPORTED: https://www.cambridge.org/core/journals/antiquity/article/challenging-the-boomandbust-models-the-fourth-millennium-bc-copper-mine-of-curak-in-southwest-serbia/F0CFC28ED3671D811AA2FB9077C32A02]; Miners here broke the rock with fire-setting [SUPPORTED: https://www.cambridge.org/core/journals/antiquity/article/challenging-the-boomandbust-models-the-fourth-millennium-bc-copper-mine-of-curak-in-southwest-serbia/F0CFC28ED3671D811AA2FB9077C32A02]; Miners here broke the rock with thermal shock [SUPPORTED: https://www.penn.museum/sites/expedition/the-oldest-copper-metallurgy-in-the-balkans/]; Shafts follow veins of copper ore [SUPPORTED: https://www.penn.museum/sites/expedition/the-oldest-copper-metallurgy-in-the-balkans/]; The shafts go some 15-20 metres into the hillside [SUPPORTED: https://www.penn.museum/sites/expedition/the-oldest-copper-metallurgy-in-the-balkans/]"}]'::jsonb),
    ('6848b0cc-552a-4e7d-b767-281d3658a5ac'::uuid, 'card_description', 'Only three other stones of this type have been found in the same country. All four lie on roughly the same line on a map, and this one is a granite boulder decorated with flowing spirals.', 'Flowing La Tène spirals decorate the Castlestrange Stone, an Iron Age granite boulder. Only three other stones of this type have been found in Ireland; all four lie on roughly the same line.', 'teaser-card-s042-rollback:6848b0cc-552a-4e7d-b767-281d3658a5ac:card_description', 'rollback of teaser-card-s042: card_description ''Flowing La Tène spirals decorate the Castlestrange Stone, an Iron Age granite boulder. Only three other stones of this type have been found in Ireland; all four lie on roughly the same line.'' restored on Castlestrange Stone', '368b4eb057f99880aa3e488efc8275044d8c7c9b06fa6d14946acbfaacb3ccf8|7f9c617fae24bd7409731e474ce855af7b4955c7f3038fe659256b8600a420f0|7f9c617fae24bd7409731e474ce855af7b4955c7f3038fe659256b8600a420f0', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Only three other stones of this type have been found in the same country. All four lie on roughly the same line on a map, and this one is a granite boulder decorated with flowing spirals."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "only three other stones of this type have been found in the same country [S3]; all four stones lie on roughly the same line on a map [S4]; this stone is a granite boulder [S2]; it is decorated with flowing spirals [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "This one is a granite boulder. [SUPPORTED: https://www.irishstones.org/place.aspx?p=697&i=7]; This one is decorated with flowing spirals. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=6333361]; Only three other stones of this type have been found in the same country. [SUPPORTED: https://cavanmuseum.ie/ccm/upload/files/WebItems/Guidebook_EN.pdf]; All four lie on roughly the same line on a map. [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('6cb33a13-f9ad-476e-8ab6-fe2b286103b2'::uuid, 'card_description', 'Alexander the Great conquered this mountain city in 333 BC. Later the city became the first city of Pisidia under Rome, and the ruins include a 9,000-seat theatre.', 'High-altitude Roman city, one of the best-preserved provincial towns of the Imperial period. Occupation began in the 8th millennium BC — by the time Rome arrived, the site was already ancient.', 'teaser-card-s042-rollback:6cb33a13-f9ad-476e-8ab6-fe2b286103b2:card_description', 'rollback of teaser-card-s042: card_description ''High-altitude Roman city, one of the best-preserved provincial towns of the Imperial period. Occupation began in the 8th millennium BC — by the time Rome arrived, the site was already ancient.'' restored on Sagalassos Archaeological Site', '8b84d41e93128a333d7f3e613cef69263b4d4cb093ad5e797ae671c4df2774d1|53ffba17275f08e39ff4ebc219e4078847a0aa135755c4642e94f4acce6b8ef9|53ffba17275f08e39ff4ebc219e4078847a0aa135755c4642e94f4acce6b8ef9', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Alexander the Great conquered this mountain city in 333 BC. Later the city became the first city of Pisidia under Rome, and the ruins include a 9,000-seat theatre."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Alexander the Great conquered the city [S2]; the conquest was in 333 BC [S2]; it is a mountain city [S1]; under Rome it became the ''first city of Pisidia'' [S2]; the ruins include a 9,000-seat theatre [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Alexander the Great conquered this city in 333 BC. [SUPPORTED: https://www.world-archaeology.com/features/sagalassos-2/]; It is a mountain city. [SUPPORTED: https://www.world-archaeology.com/features/sagalassos-2/]; Later the city came under Rome. [SUPPORTED: https://www.world-archaeology.com/features/sagalassos-2/]; Under Rome the city became the first city of Pisidia. [SUPPORTED: https://www.world-archaeology.com/features/sagalassos-2/]; The ruins include a theatre. [SUPPORTED: https://vici.org/vici/8024/]; The theatre has 9,000 seats. [SUPPORTED: https://vici.org/vici/8024/]"}]'::jsonb),
    ('6e1f996c-be31-4337-bd80-7a94b03a3d05'::uuid, 'card_description', 'Elephants and ostriches are painted in this cave, from walls to ceiling. The Paleolithic images use rosy and brown mineral pigments, and some animals are drawn with dots.', 'Paleolithic cave paintings of stags, buffalo, elephants, and ostriches span from walls to ceiling. Overlapping images create layers spanning thousands of years.', 'teaser-card-s042-rollback:6e1f996c-be31-4337-bd80-7a94b03a3d05:card_description', 'rollback of teaser-card-s042: card_description ''Paleolithic cave paintings of stags, buffalo, elephants, and ostriches span from walls to ceiling. Overlapping images create layers spanning thousands of years.'' restored on Khoit Tsenkher Cave Rock Art', '4395e86c885fc23bd0b6ac33e35f06d74bf73848069524e00e7e07c9e5aa3221|2809c84e264d872128369ba364d13205b7238c683913761317193b3adcb0360e|2809c84e264d872128369ba364d13205b7238c683913761317193b3adcb0360e', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Elephants and ostriches are painted in this cave, from walls to ceiling. The Paleolithic images use rosy and brown mineral pigments, and some animals are drawn with dots."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "elephants are painted in the cave [S2]; ostriches are painted in the cave [S2]; the site is a cave with paintings [S1]; the paintings run from walls to ceiling [S2]; the images are Paleolithic [S1]; they use rosy and brown mineral pigments [S2]; some animals are drawn with dots [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Elephants are painted in this cave. [SUPPORTED: http://www.mongoliancave.com/CaveEng/2]; Ostriches are painted in this cave. [SUPPORTED: http://www.mongoliancave.com/CaveEng/2]; The paintings run from walls to ceiling. [SUPPORTED: http://www.mongoliancave.com/CaveEng/2]; The images are Paleolithic. [SUPPORTED: http://www.mongoliancave.com/CaveEng/2]; The images use mineral pigments. [SUPPORTED: http://www.mongoliancave.com/CaveEng/2]; The pigments are rosy and brown. [SUPPORTED: http://www.mongoliancave.com/CaveEng/2]; Some animals are drawn with dots. [SUPPORTED: https://bumantourmongolia.com/2024/03/14/khoid-tsenkher-cave/]"}]'::jsonb),
    ('6e836171-0fc6-44e3-a2af-672a7b740d5d'::uuid, 'card_description', 'Treasure hunters, or Christians who smashed images, dug into this tomb''s chamber. The sarsen chamber had held remains of at least nine or ten people, with arrow heads and a clay pendant.', 'Near Addington in Kent, the sarsen chamber of Chestnuts Long Barrow held cremated and inhumed remains of at least nine or ten people, with arrow heads, pottery sherds and a clay pendant.', 'teaser-card-s042-rollback:6e836171-0fc6-44e3-a2af-672a7b740d5d:card_description', 'rollback of teaser-card-s042: card_description ''Near Addington in Kent, the sarsen chamber of Chestnuts Long Barrow held cremated and inhumed remains of at least nine or ten people, with arrow heads, pottery sherds and a clay pendant.'' restored on Chestnuts Long Barrow', '1e03c6e6fe87916b6433c356e58ba3732319b3a9189281b44f2a8c5926bf1d0a|7472f43ad5f7348f3f90a3d905314fb401d0d14e06c337f5c7e80fea80601b00|7472f43ad5f7348f3f90a3d905314fb401d0d14e06c337f5c7e80fea80601b00', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Treasure hunters, or Christians who smashed images, dug into this tomb''s chamber. The sarsen chamber had held remains of at least nine or ten people, with arrow heads and a clay pendant."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the tomb''s chamber was dug into [S7]; it was dug into either by treasure hunters or by iconoclastic Christians [S7]; the site is a tomb with a chamber [S1, S3, S4]; the chamber was built of sarsen stones [S3]; the chamber held remains of at least nine or ten people [S4]; arrow heads were found with the remains [S5]; a clay pendant was found with the remains [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Treasure hunters, or Christians who smashed images, dug into this tomb''s chamber. [SUPPORTED: https://www.kentarchaeology.org.uk/journal/76/excavation-chestnuts-megalithic-tomb-addington-kent]; The diggers may have been treasure hunters. [SUPPORTED: https://www.kentarchaeology.org.uk/journal/76/excavation-chestnuts-megalithic-tomb-addington-kent]; The diggers may instead have been Christians who smashed images (iconoclasts). [SUPPORTED: https://en.wikipedia.org/wiki/Addington_Long_Barrow]; The site is a tomb with a burial chamber. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=4763]; The chamber is built of sarsen (the sarsen chamber). [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=4763]; The chamber had held remains of at least nine or ten people. [SUPPORTED: https://www.kentarchaeology.org.uk/journal/76/excavation-chestnuts-megalithic-tomb-addington-kent]; Arrow heads were with the remains in the chamber. [SUPPORTED: https://www.kentarchaeology.org.uk/journal/76/excavation-chestnuts-megalithic-tomb-addington-kent]; A clay pendant was with the remains in the chamber. [SUPPORTED: https://www.kentarchaeology.org.uk/journal/76/excavation-chestnuts-megalithic-tomb-addington-kent]"}]'::jsonb),
    ('701203f2-92b6-4631-ab3e-aab9a5a796be'::uuid, 'card_description', 'Eight sections, like a wheel with eight spokes, form this early Bronze Age mound. Each section was built separately, its turf perhaps brought from where the builders of that section lived.', 'Skelhøj, a Bronze Age mound of the 15th century BC, rose in sections like a spoked wheel; water covered its oak coffin soon after burial, forming what archaeologists call an iron capsule.', 'teaser-card-s042-rollback:701203f2-92b6-4631-ab3e-aab9a5a796be:card_description', 'rollback of teaser-card-s042: card_description ''Skelhøj, a Bronze Age mound of the 15th century BC, rose in sections like a spoked wheel; water covered its oak coffin soon after burial, forming what archaeologists call an iron capsule.'' restored on Skelhøj', '2baec6ff5488b12544e7e027bb055cf0997718315f8c06c1c27bed01f5635b22|3f39bc35f4fac6b72e815bfe87a47fdc7a27936e20f5c904111802536b7c08f5|3f39bc35f4fac6b72e815bfe87a47fdc7a27936e20f5c904111802536b7c08f5', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Eight sections, like a wheel with eight spokes, form this early Bronze Age mound. Each section was built separately, its turf perhaps brought from where the builders of that section lived."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-005 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the mound is made of eight sections [S5]; the sections are evocative of an eight-spoked wheel [S5]; it is an early Bronze Age burial mound [S1]; each section was built independently [S5]; the builders perhaps brought turf from where they lived [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Eight sections form this mound [SUPPORTED: https://www.visit-vejen.com/visitvejen/planlaeg-din-tur/skelhoj-barrow-tobol-gdk916980]; The eight sections are laid out like a wheel with eight spokes [SUPPORTED: https://www.visit-vejen.com/visitvejen/planlaeg-din-tur/skelhoj-barrow-tobol-gdk916980]; The mound dates to the early Bronze Age [SUPPORTED: https://link.springer.com/article/10.1007/s00334-007-0109-7]; Each section was built separately [SUPPORTED: https://www.visit-vejen.com/visitvejen/planlaeg-din-tur/skelhoj-barrow-tobol-gdk916980]; The mound is built of turf [SUPPORTED: https://www.visit-vejen.com/visitvejen/planlaeg-din-tur/skelhoj-barrow-tobol-gdk916980]; Each section''s turf was perhaps brought from where the builders of that section lived [SUPPORTED: https://slks.dk/arkaeologisk-strategier/bronzealder-1800-500-fkr/gravfund]"}]'::jsonb),
    ('7155aa5a-4eff-4b1d-a105-b15d17b786c6'::uuid, 'card_description', 'Fossil bones of hippos, elephants and cave lions turned up in this cave. In 1821, William Buckland showed that hyenas had brought the bones in, using the cave as a den.', 'Quarry workers found Kirkdale Cave in 1821. Inside lay bones of hippopotamuses, elephants and cave lions, brought not by the Biblical flood but by hyenas that used it as a den.', 'teaser-card-s042-rollback:7155aa5a-4eff-4b1d-a105-b15d17b786c6:card_description', 'rollback of teaser-card-s042: card_description ''Quarry workers found Kirkdale Cave in 1821. Inside lay bones of hippopotamuses, elephants and cave lions, brought not by the Biblical flood but by hyenas that used it as a den.'' restored on Kirkdale Cave', 'b946a91522ba54290a83c8496f578361c2b5807098dcdb1ac5ee5ab7b76b1056|e146845a9a7539ecc13bc07d429ac2be2a757ffe17bf27a83a1bf8e031e0beeb|e146845a9a7539ecc13bc07d429ac2be2a757ffe17bf27a83a1bf8e031e0beeb', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Fossil bones of hippos, elephants and cave lions turned up in this cave. In 1821, William Buckland showed that hyenas had brought the bones in, using the cave as a den."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-005 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "fossil bones were found in this cave [S3]; they include hippopotamus bones [S3]; they include elephant bones [S3]; they include cave lion bones [S3]; William Buckland analysed the cave in 1821 [S2]; he determined that hyenas had brought the bones in [S2]; the hyenas used the cave as a den [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Fossil bones of hippos turned up in this cave [SUPPORTED: https://morethanadodo.com/2022/03/06/beyond-buckland/]; Fossil bones of elephants turned up in this cave [SUPPORTED: https://www.natstand.org.uk/kirkdale.htm]; Fossil bones of cave lions turned up in this cave [SUPPORTED: https://www.natstand.org.uk/kirkdale.htm]; The bones are fossil (ancient) bones [SUPPORTED: https://www.natstand.org.uk/kirkdale.htm]; William Buckland showed that hyenas had brought the bones in [SUPPORTED: https://morethanadodo.com/2022/03/06/beyond-buckland/]; The hyenas used the cave as a den [SUPPORTED: https://morethanadodo.com/2022/03/06/beyond-buckland/]; Buckland''s work on the cave took place in 1821 [SUPPORTED: https://www.ypsyork.org/wp-content/uploads/2020/02/HOGG-YPS-York-Meeting-Kirkdale-Cave-Field-Booklet-Oct-2019-ONLINE.pdf]"}]'::jsonb),
    ('75f2454d-5538-42ea-87b2-ba091dec3df6'::uuid, 'card_description', 'A search for a Roman road in 1984 turned up this prehistoric settlement. Two Early Neolithic longhouses came to light, among the best preserved examples in Britain.', NULL, 'teaser-card-s042-rollback:75f2454d-5538-42ea-87b2-ba091dec3df6:card_description', 'rollback of teaser-card-s042: card_description None restored on Lismore Fields', '8f0755d034b15ab53207d56930e90d82873bb77986a41e1835ecdf0268b0eaca|1ce66801970c215313edf0f9dc20551c97da01c836d6ee455faa76212a8a4296|1ce66801970c215313edf0f9dc20551c97da01c836d6ee455faa76212a8a4296', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A search for a Roman road in 1984 turned up this prehistoric settlement. Two Early Neolithic longhouses came to light, among the best preserved examples in Britain."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the settlement was found during a search for a Roman road [S1]; it was found in 1984 [S1]; it is a prehistoric settlement [S1]; two Early Neolithic longhouses were uncovered [S2]; they are among the best-preserved examples in Britain [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A search for a Roman road turned up this settlement. [SUPPORTED: https://buxtonmuseumandartgallery.wordpress.com/2023/10/10/lismore-fields-a-surprise-find/]; The settlement was turned up in 1984. [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR373]; The settlement is prehistoric. [SUPPORTED: https://buxtonmuseumandartgallery.wordpress.com/2023/10/10/lismore-fields-a-surprise-find/]; Two longhouses came to light. [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR373]; The longhouses are Early Neolithic. [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR373]; The longhouses are among the best preserved examples in Britain. [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR373]"}]'::jsonb),
    ('76174b71-0f02-43bd-9655-c4a489e54aa5'::uuid, 'card_description', 'Not until 1989 did scientists document the rock art here. A national museum files the site as G-540-Pd, inside a protected area that UNESCO made World Heritage.', 'A petroglyph site with at least 465 carved rocks and boulders spread across a volcanic landscape. The carvings span over a thousand years of indigenous expression.', 'teaser-card-s042-rollback:76174b71-0f02-43bd-9655-c4a489e54aa5:card_description', 'rollback of teaser-card-s042: card_description ''A petroglyph site with at least 465 carved rocks and boulders spread across a volcanic landscape. The carvings span over a thousand years of indigenous expression.'' restored on El Pedregal Archaeological Site', '0d4d60e86e04e2315cebf2b906edabe9b440fea26fa22e588782a61b307b8d9a|76f05e92b6ee69ec40155f278c81c4bc9d7ef5c449aba602e5cc39bef49fdd0f|76f05e92b6ee69ec40155f278c81c4bc9d7ef5c449aba602e5cc39bef49fdd0f', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Not until 1989 did scientists document the rock art here. A national museum files the site as G-540-Pd, inside a protected area that UNESCO made World Heritage."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site holds rock art [S1]; it was first scientifically documented in 1989 [S2]; a national museum catalogues the site [S2]; its catalogue key is G-540-Pd [S2]; the site lies inside a protected area [S3]; UNESCO designated that area a World Heritage Site [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A national museum files the site as G-540-Pd. [SUPPORTED: https://de.wikipedia.org/wiki/El_Pedregal_(Costa_Rica)]; There is rock art here. [SUPPORTED: https://semanariouniversidad.com/cultura/el-arte-rupestre-que-brilla-despues-de-llover/]; Scientists documented the rock art here in 1989. [SUPPORTED: https://de.wikipedia.org/wiki/El_Pedregal_(Costa_Rica)]; Not until 1989 did scientists document the rock art (no earlier scientific documentation). [SUPPORTED: https://de.wikipedia.org/wiki/El_Pedregal_(Costa_Rica)]; The site lies inside a protected area. [SUPPORTED: https://de.wikipedia.org/wiki/El_Pedregal_(Costa_Rica)]; UNESCO made that protected area World Heritage. [SUPPORTED: https://semanariouniversidad.com/cultura/el-arte-rupestre-que-brilla-despues-de-llover/]"}]'::jsonb),
    ('766f1ffd-9ef3-4b3e-9127-cceea9f98540'::uuid, 'card_description', 'Walls eight feet thick turned a steep slope here into a major obstacle. In medieval times, the walled site on its small limestone knoll served as a summer shelter.', 'On the limestone pavement of Great Asby Scar lie the ruins of Castle Folds, a Romano-British walled settlement where about a dozen stone huts were built into the walls around an open centre.', 'teaser-card-s042-rollback:766f1ffd-9ef3-4b3e-9127-cceea9f98540:card_description', 'rollback of teaser-card-s042: card_description ''On the limestone pavement of Great Asby Scar lie the ruins of Castle Folds, a Romano-British walled settlement where about a dozen stone huts were built into the walls around an open centre.'' restored on Castle Folds', '54b71482371eb097745aa85c8ab1534533ed77e4c98bd7fed49c2b4bde62c230|ee1620b5417f23436cd343615899077340fbbcb91d3b09030a6dc9e7bc3ebbd2|ee1620b5417f23436cd343615899077340fbbcb91d3b09030a6dc9e7bc3ebbd2', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Walls eight feet thick turned a steep slope here into a major obstacle. In medieval times, the walled site on its small limestone knoll served as a summer shelter."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the walls were eight feet thick [S5]; the walls extended a steep slope into a significant obstacle [S5]; in medieval times the site served as a summer shelter [S2]; the site is walled [S1, S5]; it stands on a small knoll on limestone [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Walls eight feet thick turned a steep slope here into a major obstacle. [SUPPORTED: http://www.gatehouse-gazetteer.info/English%20sites/3892.html]; The walls were eight feet thick. [SUPPORTED: http://www.gatehouse-gazetteer.info/English%20sites/3892.html]; The walls and slope formed a major obstacle. [SUPPORTED: http://www.gatehouse-gazetteer.info/English%20sites/3892.html]; The site is walled. [SUPPORTED: http://www.gatehouse-gazetteer.info/English%20sites/3892.html]; The site sits on a small limestone knoll. [SUPPORTED: http://www.gatehouse-gazetteer.info/English%20sites/3892.html]; In medieval times the site served as a shelter (a shieling). [SUPPORTED: http://www.gatehouse-gazetteer.info/English%20sites/3892.html]; The medieval shelter was a summer shelter. [SUPPORTED: https://walkingtheoldways.wordpress.com/2018/06/11/walking-to-castle-folds-a-romano-british-settlement/]"}]'::jsonb),
    ('768e341f-d9fa-4a3c-a4bf-27d099d7f6da'::uuid, 'card_description', 'After Trajan conquered Dacia, this town became a civilian and military centre. Roman forts went up in the area, and the Tabula Peutingeriana shows the town between Romula and Rusidava.', 'On the Olt river near the lower Danube, Acidava grew from a Dacian town into a Roman fort on the Limes Alutanus, a line of fortifications set to watch the Roxolani to the east.', 'teaser-card-s042-rollback:768e341f-d9fa-4a3c-a4bf-27d099d7f6da:card_description', 'rollback of teaser-card-s042: card_description ''On the Olt river near the lower Danube, Acidava grew from a Dacian town into a Roman fort on the Limes Alutanus, a line of fortifications set to watch the Roxolani to the east.'' restored on Acidava', '6250a0eea13b8001e67a6f2746e6208ef6f4b68b5d0141a82231048c62bc48c4|e85976d055ab59a096d73041e96c4bddf3f9d3c5998ff9039ca34d3a722e691c|e85976d055ab59a096d73041e96c4bddf3f9d3c5998ff9039ca34d3a722e691c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "After Trajan conquered Dacia, this town became a civilian and military centre. Roman forts went up in the area, and the Tabula Peutingeriana shows the town between Romula and Rusidava."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-004 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Trajan conquered Dacia [S3]; the site is a town [S1]; after the conquest the town became a civilian and military centre [S3]; Roman forts (castra) were built in the area [S3]; the Tabula Peutingeriana depicts the town [S6]; it is shown between Romula and Rusidava [S6]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "The Tabula Peutingeriana shows the town between Romula and Rusidava. [SUPPORTED: https://topostext.org/work/236]; Acidava was a town. [SUPPORTED: https://en.wikipedia.org/wiki/Acidava_(castra)]; Trajan conquered Dacia. [SUPPORTED: https://en.wikipedia.org/wiki/Trajan%27s_Dacian_Wars]; After Trajan conquered Dacia, the town became a military centre. [SUPPORTED: https://ro.wikipedia.org/wiki/Castrul_roman_Acidava]; After the conquest the town became a civilian centre. [SUPPORTED: https://ro.wikipedia.org/wiki/Castrul_roman_Acidava]; Roman forts went up in the area. [SUPPORTED: https://ro.wikipedia.org/wiki/Castrul_roman_Acidava]"}]'::jsonb),
    ('76cfc1e7-19cc-48fc-a64b-b47f1767640a'::uuid, 'card_description', 'Octopuses and hunting scenes decorate painted coffins found in this cemetery. The tombs date to about 1420-1190 BC, and every one of their entrances faces east.', 'A Minoan cemetery from the 2nd millennium BC with over 230 rock-cut chamber tombs. Funeral offerings include bronze weapons, pottery, and gold jewelry.', 'teaser-card-s042-rollback:76cfc1e7-19cc-48fc-a64b-b47f1767640a:card_description', 'rollback of teaser-card-s042: card_description ''A Minoan cemetery from the 2nd millennium BC with over 230 rock-cut chamber tombs. Funeral offerings include bronze weapons, pottery, and gold jewelry.'' restored on Armeni - Archaeological Site', '596a8e20c62a5e9478cecabe4b75f0652849431e2de7e36e5b54c520241569c9|f35de56eac90d474ee39d8d30a9e952f5705941b05ec2a208d95d0604b38021c|f35de56eac90d474ee39d8d30a9e952f5705941b05ec2a208d95d0604b38021c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-012", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Octopuses and hunting scenes decorate painted coffins found in this cemetery. The tombs date to about 1420-1190 BC, and every one of their entrances faces east."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "painted coffins (larnakes) were found at the site [S2]; the painted coffins are decorated with octopuses [S2]; the painted coffins are decorated with hunting scenes [S2]; the site is a cemetery [S1]; the tombs date to about 1420-1190 BC [S1]; every tomb entrance faces east [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Octopuses decorate painted coffins found in this cemetery. [SUPPORTED: https://www.ancientworldmagazine.com/articles/cemetery-armenoi/]; Hunting scenes decorate painted coffins found in this cemetery. [SUPPORTED: http://www.minoancrete.com/armeni.htm]; Painted coffins were found in this cemetery. [SUPPORTED: https://culturalroutes-efareth.culture.gov.gr/en/archaeological-sites/%CE%B7-%CE%BD%CE%B5%CE%BA%CF%81%CE%BF%CF%80%CE%BF%CE%BB%CE%B7-%CF%84%CF%89%CE%BD-%CE%B1%CF%81%CE%BC%CE%B5%CE%BD%CF%89%CE%BD/]; The site is a cemetery. [SUPPORTED: https://culturalroutes-efareth.culture.gov.gr/en/archaeological-sites/%CE%B7-%CE%BD%CE%B5%CE%BA%CF%81%CE%BF%CF%80%CE%BF%CE%BB%CE%B7-%CF%84%CF%89%CE%BD-%CE%B1%CF%81%CE%BC%CE%B5%CE%BD%CF%89%CE%BD/]; The tombs date to about 1420-1190 BC. [SUPPORTED: https://culturalroutes-efareth.culture.gov.gr/en/archaeological-sites/%CE%B7-%CE%BD%CE%B5%CE%BA%CF%81%CE%BF%CF%80%CE%BF%CE%BB%CE%B7-%CF%84%CF%89%CE%BD-%CE%B1%CF%81%CE%BC%CE%B5%CE%BD%CF%89%CE%BD/]; Every one of the tombs'' entrances faces east. [SUPPORTED: https://www.ancientworldmagazine.com/articles/cemetery-armenoi/]"}]'::jsonb),
    ('84c1ff70-a242-423d-96f8-694b1b7fcc67'::uuid, 'card_description', 'Animal fossils and 874 stone tools turned up in this high cave. The tools are shaped like those from the Azokh and Tağlar caves, and the dig found 6 cultural layers.', 'Gazma Cave, a Paleolithic dwelling site 1450 m above sea level, revealed 6 cultural layers, fauna fossils and 874 stone tools, similar in form to those from Azokh and Tağlar caves.', 'teaser-card-s042-rollback:84c1ff70-a242-423d-96f8-694b1b7fcc67:card_description', 'rollback of teaser-card-s042: card_description ''Gazma Cave, a Paleolithic dwelling site 1450 m above sea level, revealed 6 cultural layers, fauna fossils and 874 stone tools, similar in form to those from Azokh and Tağlar caves.'' restored on Gazma Cave', '6b82f9da249f3d7c441ebde2e753eb144f5309c4c4c7f097e0e169fdf809d4fc|f8dd9225240ced2f2c7c20fb1ae8ce23a0aff5179f835a0f5569522b6cf6222d|f8dd9225240ced2f2c7c20fb1ae8ce23a0aff5179f835a0f5569522b6cf6222d', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-013", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Animal fossils and 874 stone tools turned up in this high cave. The tools are shaped like those from the Azokh and Tağlar caves, and the dig found 6 cultural layers."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "animal (fauna) fossils were found in the cave [S4]; 874 stone tools were found in the cave [S4]; the cave lies high up (1450 m above sea level) [S2]; the tools are similar in form to those from Azokh and Tağlar caves [S5]; 6 cultural layers were found in the cave [S6]; the cave was excavated (a dig) [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Animal fossils turned up in this cave (Gazma/Qazma Cave, Nakhchivan, Azerbaijan) [SUPPORTED: https://news.milli.az/society/840213.html]; 874 stone tools turned up in the cave [SUPPORTED: https://news.milli.az/society/840213.html]; The cave is high (up in the mountains) [SUPPORTED: https://news.milli.az/society/840213.html]; The tools are shaped like those from the Azokh cave [SUPPORTED: https://news.milli.az/society/840213.html]; The tools are shaped like those from the Tağlar cave [SUPPORTED: https://news.milli.az/society/840213.html]; The dig found 6 cultural layers [SUPPORTED: https://az.wikipedia.org/wiki/Qazma_ma%C4%9Faras%C4%B1]"}]'::jsonb),
    ('88897642-cf8a-48c2-a9a4-ebb0408a8804'::uuid, 'card_description', 'An intact burial chamber still lies under one of these two Bronze Age graves. The lower grave, near the foot of the steep slope, is more damaged and keeps only two of its original capstones.', 'On a steep slope above Crow Sound, Innisidgen keeps two Bronze Age entrance graves. The upper, known as the Giant''s Grave, holds an intact burial chamber under a mound of earth and rubble.', 'teaser-card-s042-rollback:88897642-cf8a-48c2-a9a4-ebb0408a8804:card_description', 'rollback of teaser-card-s042: card_description "On a steep slope above Crow Sound, Innisidgen keeps two Bronze Age entrance graves. The upper, known as the Giant''s Grave, holds an intact burial chamber under a mound of earth and rubble." restored on Innisidgen', '8b4d1afbbaca23e55bb6f1f3d35bf0d564a24a2c78d89179f9fe9f918bd4df83|621e172b326a25cfd7b62882e17464e5ae90a6b9b224dc8fb3e5b71cd2acfb8a|621e172b326a25cfd7b62882e17464e5ae90a6b9b224dc8fb3e5b71cd2acfb8a', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An intact burial chamber still lies under one of these two Bronze Age graves. The lower grave, near the foot of the steep slope, is more damaged and keeps only two of its original capstones."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-004 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site has two graves [S1]; the graves are Bronze Age [S1]; an intact burial chamber lies under one of them today [S8]; there is a lower grave [S4]; the lower grave is near the foot of the slope [S4]; the slope is steep [S2]; the lower grave is more damaged (than the upper one) [S5]; it keeps only two of its original capstones [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "There are two graves here (at Innisidgen, one on the hill and a lower one near the foot of the slope) [SUPPORTED: https://web.archive.org/web/2024/https://historicengland.org.uk/listing/the-list/list-entry/1013271]; The two graves are Bronze Age graves [SUPPORTED: https://www.english-heritage.org.uk/visit/places/innisidgen-lower-and-upper-burial-chambers/history/]; One of the two graves has an intact burial chamber [SUPPORTED: https://www.english-heritage.org.uk/visit/places/innisidgen-lower-and-upper-burial-chambers/history/]; That intact burial chamber still lies under the grave (inside its mound) [SUPPORTED: https://web.archive.org/web/2024/https://historicengland.org.uk/listing/the-list/list-entry/1013271]; The lower grave lies near the foot of the slope [SUPPORTED: https://web.archive.org/web/2024/https://historicengland.org.uk/listing/the-list/list-entry/1013271]; The slope is steep [SUPPORTED: https://web.archive.org/web/2024/https://historicengland.org.uk/listing/the-list/list-entry/1013271]; The lower grave is more damaged (than the upper one) [SUPPORTED: https://www.english-heritage.org.uk/visit/places/innisidgen-lower-and-upper-burial-chambers/history/]; The lower grave keeps only two of its original capstones [SUPPORTED: https://www.cornwalls.co.uk/history/sites/innisidgen-entrance-grave.htm]"}]'::jsonb),
    ('8a3a0f0e-6656-4b50-92ff-7f02f9f1548e'::uuid, 'card_description', 'No treasure awaited the merchant who searched this large passage grave. Dated to the Neolithic Funnel Beaker culture, the grave may have been cleared already in ancient times.', 'On the island of Møn, a 7.5 m passage leads into the 10 m chamber of Kong Asgers Høj, a Neolithic passage grave. In 1839 a merchant came seeking treasure and found it empty.', 'teaser-card-s042-rollback:8a3a0f0e-6656-4b50-92ff-7f02f9f1548e:card_description', 'rollback of teaser-card-s042: card_description ''On the island of Møn, a 7.5 m passage leads into the 10 m chamber of Kong Asgers Høj, a Neolithic passage grave. In 1839 a merchant came seeking treasure and found it empty.'' restored on Kong Asgers Høj', '7c2a7a0dd8c08dc65a705aa7e9567f47f110610f8c943a6d2f51cb06cef03bca|af08302d06ab925f8493c4377cdf443adb4e4731f1a7688de7f99fda1c50bb69|af08302d06ab925f8493c4377cdf443adb4e4731f1a7688de7f99fda1c50bb69', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-013", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "No treasure awaited the merchant who searched this large passage grave. Dated to the Neolithic Funnel Beaker culture, the grave may have been cleared already in ancient times."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a merchant searched the grave for treasure [S4]; he found no treasure (the grave was empty) [S4]; it is a large passage grave [S1]; it is dated to the Neolithic Funnel Beaker culture [S2]; the grave may have been cleared already in ancient times [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A merchant searched this passage grave (Kong Asgers Høj, Møn) and no treasure awaited him [SUPPORTED: https://da.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]; The man who searched the grave was a merchant [SUPPORTED: https://da.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]; No treasure awaited the merchant [SUPPORTED: https://da.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]; It is a passage grave [SUPPORTED: https://www.visitdenmark.com/denmark/plan-your-trip/king-asgers-hill-gdk634994]; It is a large passage grave [SUPPORTED: https://lex.dk/Kong_Asgers_H%C3%B8j]; The grave is dated to the Neolithic [SUPPORTED: https://lex.dk/Kong_Asgers_H%C3%B8j]; The grave is dated to the Funnel Beaker culture [SUPPORTED: https://da.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]; The grave may have been cleared already in ancient times [SUPPORTED: https://da.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]"}]'::jsonb),
    ('8c624c02-31b5-4058-8551-f7cec08e6359'::uuid, 'card_description', 'Of 74 obsidian pieces tested here, the bulk came from the Zangezur Mountains. A smaller share was traced to Meydan Dağ in eastern Anatolia, among the finds of this Copper Age settlement.', 'Bülövqaya, a Chalcolithic settlement on the Sarısu River, yielded painted pottery, hearths and pottery kilns, and in its analysed obsidian, material from the Zangezur Mountains predominated.', 'teaser-card-s042-rollback:8c624c02-31b5-4058-8551-f7cec08e6359:card_description', 'rollback of teaser-card-s042: card_description ''Bülövqaya, a Chalcolithic settlement on the Sarısu River, yielded painted pottery, hearths and pottery kilns, and in its analysed obsidian, material from the Zangezur Mountains predominated.'' restored on Bülövqaya', '76994929ecd5ea890d50c78361929eca9f41f0afd1a6fdd1ae3a37336fcbc5b0|0ee6e45641c7bb3383514cfe62e1c5c15a978a421cd042dcee2da2c27a264c8c|0ee6e45641c7bb3383514cfe62e1c5c15a978a421cd042dcee2da2c27a264c8c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Of 74 obsidian pieces tested here, the bulk came from the Zangezur Mountains. A smaller share was traced to Meydan Dağ in eastern Anatolia, among the finds of this Copper Age settlement."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-004 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "74 obsidian pieces from the site were analysed [S6]; most came from the Zangezur Mountains [S6]; a smaller share was attributed to Meydan Dağ [S6]; Meydan Dağ is in eastern Anatolia [S6]; the site is a settlement [S1]; it is Copper Age (Chalcolithic) [S1]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "74 obsidian pieces from this site (Bülövqaya/Bülövkaya, Nakhchivan) were tested [SUPPORTED: https://dergipark.org.tr/en/download/article-file/4570797]; The bulk of the tested obsidian came from the Zangezur Mountains [SUPPORTED: https://ajaa.az/index.php/pub/article/download/38/11/122]; A smaller share was traced to Meydan Dağ [SUPPORTED: https://ajaa.az/index.php/pub/article/download/38/11/122]; Meydan Dağ lies in eastern Anatolia [SUPPORTED: https://ajaa.az/index.php/pub/article/view/38]; The obsidian pieces were among the finds of this settlement [SUPPORTED: https://dergipark.org.tr/en/download/article-file/4570797]; The site is a Copper Age (Chalcolithic) settlement [SUPPORTED: https://ajaa.az/index.php/pub/article/download/38/11/122]"}]'::jsonb),
    ('8cead41d-19f8-45cf-9dc0-144583641e4f'::uuid, 'card_description', 'A crescent moon: that is the rough outline of this royal palace''s walls. The palace takes its names from that shape, and one more name means where the king resides.', 'Walls shaped like a crescent moon gave Banwolseong its name: a royal palace of Silla in what is now Gyeongju, used through both the Silla and Unified Silla periods.', 'teaser-card-s042-rollback:8cead41d-19f8-45cf-9dc0-144583641e4f:card_description', 'rollback of teaser-card-s042: card_description ''Walls shaped like a crescent moon gave Banwolseong its name: a royal palace of Silla in what is now Gyeongju, used through both the Silla and Unified Silla periods.'' restored on Banwolseong', '49faa1f9f4b485523989ef2c604f171e3f207168f64afaa6d1fcc5de12d8f127|ac4df7267c116efaf8f46007083b119fb2f12a9667a8aa81323f789be3878d0d|ac4df7267c116efaf8f46007083b119fb2f12a9667a8aa81323f789be3878d0d', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A crescent moon: that is the rough outline of this royal palace''s walls. The palace takes its names from that shape, and one more name means where the king resides."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-004 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a royal palace [S1]; its walls have the rough outline of a crescent moon [S4]; the palace takes its names from that shape [S4]; the palace has several names [S5]; one more name means where the king resides [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "The rough outline of this royal palace''s walls (Wolseong/Banwolseong, Gyeongju) is a crescent moon [SUPPORTED: https://heritage.go.kr/DATA1/heritage/hub_img/html/cul_1333700160000.html?time=]; It is a royal palace (of Silla) [SUPPORTED: https://heritage.go.kr/DATA1/heritage/hub_img/html/cul_1333700160000.html?time=]; The palace is enclosed by walls (whose outline gives the shape) [SUPPORTED: https://heritage.go.kr/DATA1/heritage/hub_img/html/cul_1333700160000.html?time=]; The palace takes its names from that shape [SUPPORTED: https://heritage.go.kr/DATA1/heritage/hub_img/html/cul_1333700160000.html?time=]; One more name of the palace means where the king resides [SUPPORTED: https://heritage.go.kr/DATA1/heritage/hub_img/html/cul_1333700160000.html?time=]"}]'::jsonb),
    ('9072416f-69c6-4c4a-a5d3-6981eb899114'::uuid, 'card_description', 'Walls seven metres wide still stand two metres high around this stone enclosure. The site was dug in the 1920s, and more than twenty stone cairns ring the enclosure.', 'When built, Kastelli Giant''s Church would have stood on a rocky shoreline: a stone enclosure of around 60 by 35 metres, its walls seven metres wide, ringed by more than twenty cairns.', 'teaser-card-s042-rollback:9072416f-69c6-4c4a-a5d3-6981eb899114:card_description', 'rollback of teaser-card-s042: card_description "When built, Kastelli Giant''s Church would have stood on a rocky shoreline: a stone enclosure of around 60 by 35 metres, its walls seven metres wide, ringed by more than twenty cairns." restored on Kastelli Giant''s Church', '4f9302cc28aa7b3f14b6e72f7ff897d5c973fad647461e943fd531edc006308d|8e732ea3fadf3eee625c329758aa65d6f49fb8020fdff67e18dceccec59b2794|8e732ea3fadf3eee625c329758aa65d6f49fb8020fdff67e18dceccec59b2794', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-013", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Walls seven metres wide still stand two metres high around this stone enclosure. The site was dug in the 1920s, and more than twenty stone cairns ring the enclosure."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the walls are seven metres wide [S5]; the walls survive to a height of two metres [S5]; the site is a stone enclosure [S1, S4]; the site was excavated in the 1920s [S8]; more than twenty stone cairns surround the enclosure [S7]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "This site is a stone enclosure surrounded by walls (a Giant''s Church in Finland) [SUPPORTED: https://www.kyppi.fi/palveluikkuna/mjreki/read/asp/r_kohde_det.aspx?KOHDE_ID=582010001]; The walls are seven metres wide [SUPPORTED: https://fi.wikipedia.org/wiki/Pattijoen_Kastelli]; The walls still stand two metres high [SUPPORTED: https://www.kyppi.fi/palveluikkuna/mjreki/read/asp/r_kohde_det.aspx?KOHDE_ID=582010001]; The site was dug in the 1920s [SUPPORTED: https://www.kyppi.fi/palveluikkuna/mjreki/read/asp/r_kohde_det.aspx?KOHDE_ID=582010001]; More than twenty stone cairns ring the enclosure [SUPPORTED: https://www.kyppi.fi/palveluikkuna/mjreki/read/asp/r_kohde_det.aspx?KOHDE_ID=582010001]"}]'::jsonb),
    ('919ca5f2-4d3b-474a-b7f5-1b706473797c'::uuid, 'card_description', 'Almost every inner wall of this Roman burial site was chiselled down. The floor was lowered by several metres too, leaving two linked halls on split levels in a valley slope.', 'Dug into Globigerina Limestone on a slope of Lunzjata Valley, the Għar Għerduf Catacombs are the only surviving early Christian catacombs in Gozo, with arcosolia hewn into their walls.', 'teaser-card-s042-rollback:919ca5f2-4d3b-474a-b7f5-1b706473797c:card_description', 'rollback of teaser-card-s042: card_description ''Dug into Globigerina Limestone on a slope of Lunzjata Valley, the Għar Għerduf Catacombs are the only surviving early Christian catacombs in Gozo, with arcosolia hewn into their walls.'' restored on Għar Għerduf Catacombs', '31545bdff90939517c37efadd995a950258e67f62dbb8046127bfa891c78338e|aa11c9a19b38e027fcf6b0a9e87888041639d16e5e60864e6eb730d3ea0abdc9|aa11c9a19b38e027fcf6b0a9e87888041639d16e5e60864e6eb730d3ea0abdc9', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-014", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Almost every inner wall of this Roman burial site was chiselled down. The floor was lowered by several metres too, leaving two linked halls on split levels in a valley slope."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "almost all the inner walls (the internal partitions) were chiselled down [S7]; it is a Roman burial site [S2]; the floor was lowered by several metres [S7]; this left two linked halls [S7]; the halls are on split levels [S7]; the site lies in a valley slope [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "This is a Roman burial site [SUPPORTED: https://archsoc.org.mt/ghar-gherduf/]; Almost every inner wall of the site was chiselled down [SUPPORTED: https://www.archsoc.org.mt/wp-content/uploads/2018/04/G%C4%A7ar-Gerduf-Seminar-Programme.pdf]; The floor was lowered too [SUPPORTED: https://www.archsoc.org.mt/wp-content/uploads/2018/04/G%C4%A7ar-Gerduf-Seminar-Programme.pdf]; The floor was lowered by several metres [SUPPORTED: https://www.archsoc.org.mt/wp-content/uploads/2018/04/G%C4%A7ar-Gerduf-Seminar-Programme.pdf]; The lowering left two halls [SUPPORTED: https://www.archsoc.org.mt/wp-content/uploads/2018/04/G%C4%A7ar-Gerduf-Seminar-Programme.pdf]; The two halls are linked and on split levels [SUPPORTED: https://www.archsoc.org.mt/wp-content/uploads/2018/04/G%C4%A7ar-Gerduf-Seminar-Programme.pdf]; The site lies in a valley slope [SUPPORTED: https://newsbook.com.mt/en/plans-to-build-house-just-outside-gozos-only-roman-catacombs-revived/]"}]'::jsonb),
    ('92d26614-c2fb-4b94-9342-99a5bd2407ab'::uuid, 'card_description', 'Flint tools and weapons dating to 3600 BC were found at this hillfort. A TV dig had dated the start of the Iron Age fort to about 600 BC, on a ridge used long before.', 'Caerau Hillfort crowns a ridge-top plateau in Cardiff, an Iron Age fort occupied from about 600 BC, yet built on a Neolithic site where flint tools and weapons dating to 3600 BC were found.', 'teaser-card-s042-rollback:92d26614-c2fb-4b94-9342-99a5bd2407ab:card_description', 'rollback of teaser-card-s042: card_description ''Caerau Hillfort crowns a ridge-top plateau in Cardiff, an Iron Age fort occupied from about 600 BC, yet built on a Neolithic site where flint tools and weapons dating to 3600 BC were found.'' restored on Caerau Hillfort', 'df4d661deccc44638255d29447461ca2f51812f39602bbd5ca322a49235f7cba|a31008fab21c0bc1da9930cd30266e9f7c6ead30e28a6619b27aa783c75990f2|a31008fab21c0bc1da9930cd30266e9f7c6ead30e28a6619b27aa783c75990f2', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-014", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Flint tools and weapons dating to 3600 BC were found at this hillfort. A TV dig had dated the start of the Iron Age fort to about 600 BC, on a ridge used long before."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "flint tools and weapons were found at the site [S4]; they date to 3600 BC [S4]; the site is a hillfort [S1]; a TV excavation dated the start of the hillfort''s occupation to about 600 BC [S2]; the fort is Iron Age [S1]; it stands on a ridge [S1]; the place was used (occupied) long before the fort [S1, S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Flint tools were found at this hillfort [SUPPORTED: https://archwilio.org.uk/arch/query/page.php?watprn=GGAT07852s&dbname=ggat&tbname=core]; Flint weapons were found at this hillfort [SUPPORTED: https://archwilio.org.uk/arch/query/page.php?watprn=GGAT07852s&dbname=ggat&tbname=core]; The flint tools and weapons date to 3600 BC [SUPPORTED: https://archwilio.org.uk/arch/query/page.php?watprn=GGAT07852s&dbname=ggat&tbname=core]; A TV dig took place at the hillfort [SUPPORTED: https://coflein.gov.uk/en/sites/94517]; The TV dig had dated the start of the fort to about 600 BC [SUPPORTED: https://coflein.gov.uk/en/sites/94517]; The fort is an Iron Age fort [SUPPORTED: https://coflein.gov.uk/en/sites/94517]; The fort stands on a ridge [SUPPORTED: https://archwilio.org.uk/arch/query/page.php?watprn=GGAT00093s&dbname=ggat&tbname=core]; The ridge was used long before the Iron Age fort [SUPPORTED: https://coflein.gov.uk/en/sites/94517]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 35;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s042-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s042-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s042-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 35 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('4d446438-7613-43d2-b95e-c6f1acf9109d'::uuid, 'card_description', 'Big-game hunting gives way to herding in the figures of this rock art. Along a river valley, the figures, over 10,000 of them, go on to show nomads who depended on horses.'), ('4f32070e-25b0-4f96-a895-37499099f745'::uuid, 'card_description', 'Nothing of this Neolithic site shows at ground level. Birmingham Archaeology probed the site from 2002 to 2004, and from the air the features appear as cropmarks.'), ('521ade1a-0eaf-442b-973d-ccae9e9fbb35'::uuid, 'card_description', 'Found in two pieces, this granite stone was rejoined in the 1990s. The giant is believed to be the largest standing stone of the Iberian Peninsula carved entirely by humans.'), ('539b56ad-5705-40c1-848b-767710247e7c'::uuid, 'card_description', 'Diggers found the remains of some 15 to 30 people in this low stone chamber. Its roof is one very large slab, resting on only three of the uprights, and half of their height lies buried.'), ('561ba9a0-09a5-4954-b137-f5c7dbdb0349'::uuid, 'card_description', 'An emperor born in the city raised this beacon tower over its harbour. Septimius Severus also expanded that harbour, and his tower of many stories reached about 35 metres in height.'), ('56876b69-7222-4afd-8204-5f1f00bd0725'::uuid, 'card_description', 'A bronze sword and a gilt belt hook lay in a Bronze Age grave here. They bore the same motif as two engraved granite stones at the site, proof that the mound and the stones are of one date.'), ('56f3ec0c-0610-4701-8a4e-727b7d3a2512'::uuid, 'card_description', 'Foundations of 160 round stone structures sit on this butte. Over 460 rock carvings and a prehistoric garden beside the hill show how much it mattered to the ancient Hohokam.'), ('577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1'::uuid, 'card_description', 'Of three hill forts on this hill, quarrying has largely taken two. The last ''intact'' survivor sits on a sloping ridge top, with ramparts up to three metres high and a commanding view.'), ('585ae9f5-c9ef-4446-84e9-a2c5825f5eda'::uuid, 'card_description', 'Japanese found this two-room tomb during their occupation of the peninsula. Its back room holds a painting on the north wall, and the Koguryo tomb is now listed as a National Treasure.'), ('59a722b9-4281-4426-8144-284e509f2061'::uuid, 'card_description', 'Dynamite brought down the clock tower that once stood on this Roman bastion. Emperor Hadrian''s fortress of the 2nd century AD had four corner towers, and the bastion is the sole survivor.'), ('5df03f8d-0b22-4188-b7ae-ccd2b00d8f47'::uuid, 'card_description', 'Stone monuments at two Maya cities record king Ch''iyel''s visit to Ixkun. His city sat on a key trade route through the Maya Mountains, and the two appear to have formed a military alliance.'), ('5e13b5f1-b63f-49fa-96e9-7adad6c1d136'::uuid, 'card_description', 'Probably built in the Punic Wars, this round tower fell in the 3rd century AD. About seven wall courses high, the tower is the best preserved of the country''s Punic-Roman towers.'), ('5f22c11c-22a4-4776-9120-75b3b9e33687'::uuid, 'card_description', 'Each winter, this floor is covered for protection, then reopened in spring. Colorful marble pieces show a figure from myth in a rare technique, one of the few surviving examples worldwide.'), ('655898a6-3d5c-40f3-8411-e6b3b185f11f'::uuid, 'card_description', 'Thousands of terracotta roof pieces lay in the debris of this building. The Early Bronze Age house had two stories, a stairway and storage areas, until fire finally destroyed the house.'), ('657dbfe1-7b3f-4548-93c6-99be8674a6ff'::uuid, 'card_description', 'James Farrer and George Petrie dug into this Neolithic tomb in 1867. They uncovered the bones of several people in a tomb similar in design to Maeshowe, later partly restored.'), ('6814a205-8ebc-46b8-8581-94c1cbb06745'::uuid, 'card_description', 'Miners here broke the rock with fire-setting and thermal shock. Shafts follow veins of copper ore, some 15-20 metres into the hillside, in one of the earliest copper mines in Europe.'), ('6848b0cc-552a-4e7d-b767-281d3658a5ac'::uuid, 'card_description', 'Only three other stones of this type have been found in the same country. All four lie on roughly the same line on a map, and this one is a granite boulder decorated with flowing spirals.'), ('6cb33a13-f9ad-476e-8ab6-fe2b286103b2'::uuid, 'card_description', 'Alexander the Great conquered this mountain city in 333 BC. Later the city became the first city of Pisidia under Rome, and the ruins include a 9,000-seat theatre.'), ('6e1f996c-be31-4337-bd80-7a94b03a3d05'::uuid, 'card_description', 'Elephants and ostriches are painted in this cave, from walls to ceiling. The Paleolithic images use rosy and brown mineral pigments, and some animals are drawn with dots.'), ('6e836171-0fc6-44e3-a2af-672a7b740d5d'::uuid, 'card_description', 'Treasure hunters, or Christians who smashed images, dug into this tomb''s chamber. The sarsen chamber had held remains of at least nine or ten people, with arrow heads and a clay pendant.'), ('701203f2-92b6-4631-ab3e-aab9a5a796be'::uuid, 'card_description', 'Eight sections, like a wheel with eight spokes, form this early Bronze Age mound. Each section was built separately, its turf perhaps brought from where the builders of that section lived.'), ('7155aa5a-4eff-4b1d-a105-b15d17b786c6'::uuid, 'card_description', 'Fossil bones of hippos, elephants and cave lions turned up in this cave. In 1821, William Buckland showed that hyenas had brought the bones in, using the cave as a den.'), ('75f2454d-5538-42ea-87b2-ba091dec3df6'::uuid, 'card_description', 'A search for a Roman road in 1984 turned up this prehistoric settlement. Two Early Neolithic longhouses came to light, among the best preserved examples in Britain.'), ('76174b71-0f02-43bd-9655-c4a489e54aa5'::uuid, 'card_description', 'Not until 1989 did scientists document the rock art here. A national museum files the site as G-540-Pd, inside a protected area that UNESCO made World Heritage.'), ('766f1ffd-9ef3-4b3e-9127-cceea9f98540'::uuid, 'card_description', 'Walls eight feet thick turned a steep slope here into a major obstacle. In medieval times, the walled site on its small limestone knoll served as a summer shelter.'), ('768e341f-d9fa-4a3c-a4bf-27d099d7f6da'::uuid, 'card_description', 'After Trajan conquered Dacia, this town became a civilian and military centre. Roman forts went up in the area, and the Tabula Peutingeriana shows the town between Romula and Rusidava.'), ('76cfc1e7-19cc-48fc-a64b-b47f1767640a'::uuid, 'card_description', 'Octopuses and hunting scenes decorate painted coffins found in this cemetery. The tombs date to about 1420-1190 BC, and every one of their entrances faces east.'), ('84c1ff70-a242-423d-96f8-694b1b7fcc67'::uuid, 'card_description', 'Animal fossils and 874 stone tools turned up in this high cave. The tools are shaped like those from the Azokh and Tağlar caves, and the dig found 6 cultural layers.'), ('88897642-cf8a-48c2-a9a4-ebb0408a8804'::uuid, 'card_description', 'An intact burial chamber still lies under one of these two Bronze Age graves. The lower grave, near the foot of the steep slope, is more damaged and keeps only two of its original capstones.'), ('8a3a0f0e-6656-4b50-92ff-7f02f9f1548e'::uuid, 'card_description', 'No treasure awaited the merchant who searched this large passage grave. Dated to the Neolithic Funnel Beaker culture, the grave may have been cleared already in ancient times.'), ('8c624c02-31b5-4058-8551-f7cec08e6359'::uuid, 'card_description', 'Of 74 obsidian pieces tested here, the bulk came from the Zangezur Mountains. A smaller share was traced to Meydan Dağ in eastern Anatolia, among the finds of this Copper Age settlement.'), ('8cead41d-19f8-45cf-9dc0-144583641e4f'::uuid, 'card_description', 'A crescent moon: that is the rough outline of this royal palace''s walls. The palace takes its names from that shape, and one more name means where the king resides.'), ('9072416f-69c6-4c4a-a5d3-6981eb899114'::uuid, 'card_description', 'Walls seven metres wide still stand two metres high around this stone enclosure. The site was dug in the 1920s, and more than twenty stone cairns ring the enclosure.'), ('919ca5f2-4d3b-474a-b7f5-1b706473797c'::uuid, 'card_description', 'Almost every inner wall of this Roman burial site was chiselled down. The floor was lowered by several metres too, leaving two linked halls on split levels in a valley slope.'), ('92d26614-c2fb-4b94-9342-99a5bd2407ab'::uuid, 'card_description', 'Flint tools and weapons dating to 3600 BC were found at this hillfort. A TV dig had dated the start of the Iron Age fort to about 600 BC, on a ridge used long before.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s042-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
